//! 🧪️ Independent causes and actual capacity survive allocation refusal.
use super::*;
use crate::ValueRefusalKind;
fn cause(value:&serde_json::Value)->Option<ValueError>{value.as_str().map(|text|ValueError::new(ValueRefusalKind::Canceled,text.to_owned()))}
fn port_cause(value:&serde_json::Value)->Option<NativeAllocationRefusal>{cause(value).map(NativeAllocationRefusal::Owned)}
fn original_cause(value:&Option<NativeAllocationRefusal>)->Option<&ValueError>{match value{Some(NativeAllocationRefusal::Owned(error))=>Some(error),_=>None}}
#[test]
fn allocation_failure_retains_schema_causes_and_physical_progress(){
 let fixture:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../🛬️decode/🛂️allocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for case in fixture["allocationSettlement"].as_array().unwrap(){let f=&case["failure"];let actual=case["performed"].as_bool().unwrap().then(||case["allocated"].as_u64().unwrap()as usize);let result=NativeAllocationFailure{primary:cause(&f["primary"]),admission:cause(&f["admission"]),forwarded_admission:port_cause(&f["forwardedAdmission"]),scoped_admission:port_cause(&f["scopedAdmission"]),forwarded_quote:port_cause(&f["forwardedQuote"]),scoped_quote:port_cause(&f["scopedQuote"]),forwarded_post:port_cause(&f["forwardedPost"]),scoped_post:port_cause(&f["scopedPost"]),forwarded_cancel:port_cause(&f["forwardedCancel"]),scoped_cancel:port_cause(&f["scopedCancel"]),receipt:cause(&f["receipt"]),extent:cause(&f["extent"]),progress:NativeAllocationProgress{prior_admitted_bytes:Some(case["prior"].as_u64().unwrap()as usize),requested_bytes:Some(case["requested"].as_u64().unwrap()as usize),maximum_bytes:Some(case["maximum"].as_u64().unwrap()as usize),admitted_bytes:case["admitted"].as_u64().unwrap()as usize,actual_capacity_bytes:actual}};let causes=[result.primary.as_ref(),result.admission.as_ref(),original_cause(&result.forwarded_admission),original_cause(&result.scoped_admission),original_cause(&result.forwarded_quote),original_cause(&result.scoped_quote),original_cause(&result.forwarded_post),original_cause(&result.scoped_post),original_cause(&result.forwarded_cancel),original_cause(&result.scoped_cancel),result.receipt.as_ref(),result.extent.as_ref()];for(key,value)in ["primary","admission","forwardedAdmission","scopedAdmission","forwardedQuote","scopedQuote","forwardedPost","scopedPost","forwardedCancel","scopedCancel","receipt","extent"].into_iter().zip(causes){assert_eq!(value.map(|error|error.message.as_ref()),f[key].as_str());}assert_eq!(result.is_empty(),causes.iter().all(|value|value.is_none()));assert_eq!(result.progress.actual_capacity_bytes,actual);}
}

#[test]
fn refusal_handle_transfers_only_its_actual_owner(){let cases:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../🛬️decode/🛂️allocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();assert!(cases["refusalHandleCases"].as_array().unwrap().iter().any(|case|case["sameOwner"]==false&&case["canTransfer"]==false));let mut original=NativeAllocationRefusalVault::default();let mut foreign=NativeAllocationRefusalVault::default();let handle=original.retain(ValueError::literal(ValueRefusalKind::Canceled,"original refused")).unwrap();let other=foreign.retain(ValueError::literal(ValueRefusalKind::OwnershipLimit,"other refused")).unwrap();let handle=foreign.take(handle).unwrap_err();assert!(!original.terminal_is_empty());assert!(!foreign.terminal_is_empty());assert_eq!(original.take(handle).unwrap().message.as_ref(),"original refused");assert_eq!(foreign.take(other).unwrap().message.as_ref(),"other refused");assert!(original.terminal_is_empty()&&foreign.terminal_is_empty());}

#[test]
fn original_authority_reborrows_only_its_validated_context(){
 struct Source(u8);struct Port{source:std::sync::Arc<Source>,recorded:Option<(NativeAllocationEvent,Result<(),NativeAllocationRefusal>)>}struct Context<'turn,'source>{source:&'turn Source,payload:&'source str,interrupt:bool,events:Vec<NativeAllocationEvent>}
 impl NativeAllocationAuthorityPort for Port{type Context<'turn,'source>=Context<'turn,'source> where 'source:'turn;fn validate_context<'turn,'source>(&self,context:&Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{if std::ptr::eq(self.source.as_ref(),context.source)&&self.source.0==context.source.0&&!context.payload.is_empty(){Ok(())}else{Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"foreign source context"))}}fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn receive<'reply,'turn,'source>(&mut self,context:&mut Context<'turn,'source>,event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<(),crate::NativeAllocationRefusal>{context.events.push(event);if context.payload=="deny"{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original denied").into())}if context.interrupt{context.interrupt=false;self.recorded=Some((event,Ok(())));panic!("original port interrupted after its recorded verdict")}Ok(())})();Ok(reply.complete(result))}fn recover<'reply,'turn,'source>(&mut self,context:&mut Context<'turn,'source>,event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<Option<Result<(),crate::NativeAllocationRefusal>>,ValueError>{if self.recorded.as_ref().is_some_and(|(recorded,_)|*recorded!=event){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original event changed"))}Ok(self.recorded.take().map(|(_,verdict)|verdict))})()?;Ok(match result{Some(verdict)=>reply.complete(verdict),None=>reply.pending()})}}
 let source=std::sync::Arc::new(Source(7));let foreign_source=Source(7);let text=String::from("borrowed source");let mut authority=NativeAllocationAuthority::new(Port{source:source.clone(),recorded:None});let identity=authority.identity();let mut original=Context{source:source.as_ref(),payload:&text,interrupt:true,events:Vec::new()};let mut foreign=Context{source:&foreign_source,payload:&text,interrupt:false,events:Vec::new()};let request=NativeAllocationRequest{bytes:5,owned_bytes:3,next_owned_bytes:8,maximum_bytes:8};let mut transaction=None;let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||authority.with_loan(&mut original,|loan|loan.begin(request,true,&mut transaction))));assert!(panic.is_err());assert!(authority.inspect_port(|port|std::sync::Arc::ptr_eq(&port.source,&source)&&port.recorded.is_some()));assert_eq!(transaction.as_ref().unwrap().phase(),NativeAllocationTransactionPhase::QuoteStarted);assert!(authority.with_loan(&mut foreign,|_|()).is_err());assert!(foreign.events.is_empty());let mut resumed=Context{source:source.as_ref(),payload:&text,interrupt:false,events:Vec::new()};authority.with_loan(&mut resumed,|loan|{assert_eq!(loan.identity(),identity);let state=transaction.as_mut().unwrap();assert!(loan.recover(state).unwrap());assert!(state.take_verdict().unwrap().is_ok());loan.settle(state,Some(3)).unwrap();let mut competing=None;assert!(loan.begin(request,false,&mut competing).is_err());assert!(competing.is_none());}).unwrap();let mut authority=match authority.into_port(){Err(owner)=>owner,Ok(_)=>panic!("unfinished original verdict must retain its port")};authority.with_loan(&mut resumed,|loan|{let state=transaction.as_mut().unwrap();assert!(!state.terminal_is_empty());assert!(state.take_verdict().unwrap().is_ok());assert!(!state.terminal_is_empty());let mut competing=None;assert!(loan.begin(request,false,&mut competing).is_err());loan.finish(&mut transaction).unwrap();}).unwrap();assert_eq!(original.events,[NativeAllocationEvent::Quote(request)]);assert_eq!(resumed.events,[NativeAllocationEvent::Post{request,actual:3}]);assert!(transaction.is_none());authority.with_send_loan(&mut resumed,|loan|{{let child:&mut dyn NativeSendAllocationLoan=&mut *loan;assert_eq!(child.identity(),identity);child.begin(request,false,&mut transaction).unwrap();}assert!(transaction.as_mut().unwrap().take_verdict().unwrap().is_ok());loan.finish(&mut transaction).unwrap();}).unwrap();assert_eq!(resumed.events.last(),Some(&NativeAllocationEvent::Admit(request)));let mut denied=Context{source:source.as_ref(),payload:"deny",interrupt:false,events:Vec::new()};authority.with_loan(&mut denied,|loan|loan.begin(request,false,&mut transaction)).unwrap().unwrap();let mut authority=match authority.into_port(){Err(owner)=>owner,Ok(_)=>panic!("denied original verdict must retain its port")};authority.with_loan(&mut denied,|loan|{let mut competing=None;assert!(loan.begin(request,false,&mut competing).is_err());let state=transaction.as_mut().unwrap();let refusal=state.take_verdict().unwrap().unwrap_err().into_owned().unwrap();assert_eq!(refusal.message.as_ref(),"original denied");assert!(!state.terminal_is_empty());loan.finish(&mut transaction).unwrap();}).unwrap();assert!(authority.into_port().is_ok());
}

#[test]
fn budget_settlement_consumes_matching_quote_after_grant_change(){let request=NativeAllocationRequest{bytes:5,owned_bytes:0,next_owned_bytes:5,maximum_bytes:5};let grant=crate::RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:5,maximum_depth:1,..Default::default()};let changed=crate::RetainedCloneGrant{maximum_items:2,..grant};let mut post=NativeAllocationBudget::default();post.receive(NativeAllocationEvent::Quote(request),grant,true).unwrap();assert!(post.receive(NativeAllocationEvent::Post{request,actual:3},changed,true).is_err());assert!(post.terminal_is_empty());assert_eq!(post.spent(),3);let mut combined=NativeAllocationBudget::default();combined.receive(NativeAllocationEvent::Quote(request),grant,true).unwrap();let error=combined.receive(NativeAllocationEvent::Post{request,actual:6},changed,true).unwrap_err();assert_eq!(error.message.as_ref(),"original grant changed and physical allocation exceeded its quote");assert!(combined.terminal_is_empty());assert_eq!(combined.spent(),6);let mut cancel=NativeAllocationBudget::default();cancel.receive(NativeAllocationEvent::Quote(request),grant,true).unwrap();assert!(cancel.receive(NativeAllocationEvent::Cancel(request),changed,true).is_err());assert!(cancel.terminal_is_empty());assert_eq!(cancel.spent(),0);let mut foreign=NativeAllocationBudget::default();foreign.receive(NativeAllocationEvent::Quote(request),grant,true).unwrap();let other=NativeAllocationRequest{bytes:4,next_owned_bytes:4,..request};assert!(foreign.receive(NativeAllocationEvent::Post{request:other,actual:3},grant,true).is_err());assert_eq!(foreign.pending(),Some((request,grant)));assert_eq!(foreign.spent(),0);foreign.receive(NativeAllocationEvent::Cancel(request),grant,true).unwrap();}

#[test]
fn same_owned_budget_finishes_changed_grant_post(){
 struct Port{budget:NativeAllocationBudget}
 impl NativeAllocationAuthorityPort for Port{type Context<'turn,'source>=crate::RetainedCloneGrant where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn receive<'reply,'turn,'source>(&mut self,grant:&mut Self::Context<'turn,'source>,event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<(),crate::NativeAllocationRefusal>{self.budget.receive(event,*grant,true).map_err(Into::into)})();Ok(reply.complete(result))}fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<Option<Result<(),crate::NativeAllocationRefusal>>,ValueError>{Ok(None)})()?;Ok(match result{Some(verdict)=>reply.complete(verdict),None=>reply.pending()})}}
 let request=NativeAllocationRequest{bytes:5,owned_bytes:0,next_owned_bytes:5,maximum_bytes:5};let mut original=crate::RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:5,maximum_depth:1,..Default::default()};let mut changed=crate::RetainedCloneGrant{maximum_items:2,..original};let mut authority=NativeAllocationAuthority::new(Port{budget:Default::default()});let mut transaction=None;authority.with_loan(&mut original,|loan|{loan.begin(request,true,&mut transaction).unwrap();assert!(transaction.as_mut().unwrap().take_verdict().unwrap().is_ok())}).unwrap();authority.with_loan(&mut changed,|loan|{let state=transaction.as_mut().unwrap();loan.settle(state,Some(3)).unwrap();assert!(state.take_verdict().unwrap().is_err());loan.finish(&mut transaction).unwrap()}).unwrap();assert!(authority.inspect_port(|port|port.budget.terminal_is_empty()&&port.budget.spent()==3));assert!(authority.into_port().is_ok());
}

#[test]
fn original_allocation_defers_uninvoked_post_when_the_borrowed_source_changes(){
 use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};
 struct Turn<'a>{token:&'a crate::OriginalSourceTurn,live:&'a AtomicBool,panic_next:&'a AtomicBool,panic_after:&'a AtomicUsize}
 struct Port{source:crate::OriginalSourceTurnIssuer,posts:usize,actual:Option<usize>}
 impl NativeAllocationAuthorityPort for Port{type Context<'turn,'source>=Turn<'turn> where 'source:'turn;fn validate_context<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{self.source.validate(turn.token).map_err(ValueError::from)?;if turn.panic_next.swap(false,Ordering::SeqCst){panic!("original Source validation interrupted")}if turn.panic_after.load(Ordering::SeqCst)>0&&turn.panic_after.fetch_sub(1,Ordering::SeqCst)==1{panic!("original Source dispatch validation interrupted")}if turn.live.load(Ordering::SeqCst){Ok(())}else{Err(ValueError::literal(ValueRefusalKind::Canceled,"original Source turn paused"))}}fn source_turn<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{Some(turn.token.identity())}fn receive<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<(),crate::NativeAllocationRefusal>{if let NativeAllocationEvent::Post{actual,..}=event{self.posts+=1;self.actual=Some(actual)}Ok(())})();Ok(reply.complete(result))}fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let result=(||->Result<Option<Result<(),crate::NativeAllocationRefusal>>,ValueError>{Ok(None)})()?;Ok(match result{Some(verdict)=>reply.complete(verdict),None=>reply.pending()})}}
 let source=crate::OriginalSourceTurnIssuer::new();let token=source.issue().unwrap();let live=AtomicBool::new(true);let panic_next=AtomicBool::new(false);let panic_after=AtomicUsize::new(0);let mut turn=Turn{token:&token,live:&live,panic_next:&panic_next,panic_after:&panic_after};let mut authority=NativeAllocationAuthority::new(Port{source,posts:0,actual:None});let layout=std::alloc::Layout::array::<u8>(8).unwrap();let pointer=unsafe{std::alloc::alloc(layout)};assert!(!pointer.is_null());let mut transaction=None;authority.with_send_loan(&mut turn,|loan|{let request=NativeAllocationRequest{bytes:8,owned_bytes:0,next_owned_bytes:8,maximum_bytes:8};loan.begin(request,true,&mut transaction).unwrap();assert!(transaction.as_mut().unwrap().take_verdict().unwrap().is_ok());live.store(false,Ordering::SeqCst);assert_eq!(loan.settle(transaction.as_mut().unwrap(),Some(layout.size())).unwrap_err().kind,ValueRefusalKind::Canceled);assert!(loan.matches_transaction(transaction.as_ref()));assert_eq!(loan.recover(transaction.as_mut().unwrap()).unwrap_err().kind,ValueRefusalKind::Canceled);live.store(true,Ordering::SeqCst);panic_next.store(true,Ordering::SeqCst);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.settle(transaction.as_mut().unwrap(),Some(layout.size())))).is_err());panic_after.store(2,Ordering::SeqCst);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.settle(transaction.as_mut().unwrap(),Some(layout.size())))).is_err());assert!(loan.recover(transaction.as_mut().unwrap()).unwrap());assert!(transaction.as_mut().unwrap().take_verdict().unwrap().is_ok());loan.finish(&mut transaction).unwrap();}).unwrap();assert_eq!(authority.inspect_port(|port|(port.posts,port.actual)),(1,Some(layout.size())));unsafe{std::alloc::dealloc(pointer,layout)};assert!(authority.into_port().is_ok());
}

#[test]
fn original_allocation_recovery_reply_owns_the_exact_refusal_before_unwind(){
 struct Port{refusal:Option<ValueError>,recoveries:usize}
 impl NativeAllocationAuthorityPort for Port{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError> where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn receive<'reply,'turn,'source>(&mut self,_:&mut (),_:NativeAllocationEvent,_:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{panic!("original allocation producer interrupted")}fn recover<'reply,'turn,'source>(&mut self,_:&mut (),_:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{self.recoveries+=1;let refusal=self.refusal.take().expect("actual original refusal");let completed=reply.complete(Err(refusal.into()));std::hint::black_box(&completed);panic!("original recovery interrupted after reply")}}
 let refusal=ValueError::new(ValueRefusalKind::Canceled,String::from("actual allocation refusal"));let pointer=refusal.message.as_ptr();let mut authority=NativeAllocationAuthority::new(Port{refusal:Some(refusal),recoveries:0});let mut transaction=None;authority.with_send_loan(&mut (),|loan|{let request=NativeAllocationRequest{bytes:8,owned_bytes:0,next_owned_bytes:8,maximum_bytes:8};assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.begin(request,true,&mut transaction))).is_err());assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.recover(transaction.as_mut().unwrap()))).is_err());assert!(transaction.as_mut().unwrap().take_verdict().is_none());assert!(loan.recover(transaction.as_mut().unwrap()).unwrap());let error=match transaction.as_mut().unwrap().take_verdict().unwrap().unwrap_err(){NativeAllocationRefusal::Owned(error)=>error,_=>panic!("expected exact owned refusal")};assert_eq!(error.message.as_ptr(),pointer);loan.finish(&mut transaction).unwrap();drop(error);}).unwrap();assert_eq!(authority.inspect_port(|port|port.recoveries),1);assert!(authority.into_port().is_ok());
}

#[test]
fn original_allocation_receive_reply_owns_the_exact_refusal_before_unwind(){
 struct Port{refusal:Option<ValueError>}
 impl NativeAllocationAuthorityPort for Port{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError> where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn receive<'reply,'turn,'source>(&mut self,_:&mut (),_:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{let refusal=self.refusal.take().expect("actual original refusal");let completed=reply.complete(Err(refusal.into()));std::hint::black_box(&completed);panic!("original callback interrupted after reply")}fn recover<'reply,'turn,'source>(&mut self,_:&mut (),_:NativeAllocationEvent,_:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{panic!("recorded original callback must not replay")}}
 let refusal=ValueError::new(ValueRefusalKind::Canceled,String::from("actual callback refusal"));let pointer=refusal.message.as_ptr();let mut authority=NativeAllocationAuthority::new(Port{refusal:Some(refusal)});let mut transaction=None;authority.with_send_loan(&mut (),|loan|{let request=NativeAllocationRequest{bytes:8,owned_bytes:0,next_owned_bytes:8,maximum_bytes:8};assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.begin(request,true,&mut transaction))).is_err());assert!(loan.recover(transaction.as_mut().unwrap()).unwrap());let error=match transaction.as_mut().unwrap().take_verdict().unwrap().unwrap_err(){NativeAllocationRefusal::Owned(error)=>error,_=>panic!("expected exact owned refusal")};assert_eq!(error.message.as_ptr(),pointer);loan.finish(&mut transaction).unwrap();drop(error);}).unwrap();assert!(authority.into_port().is_ok());
}

#[test]
fn original_allocation_pending_reply_keeps_the_same_transaction(){
 struct Port{saved:Option<Result<(),NativeAllocationRefusal>>,calls:usize}
 impl NativeAllocationAuthorityPort for Port{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError> where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}fn receive<'reply,'turn,'source>(&mut self,_:&mut (),event:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{self.calls+=1;if matches!(event,NativeAllocationEvent::Quote(_)){self.saved=Some(Ok(()));Ok(reply.pending())}else{Ok(reply.complete(Ok(())))}}fn recover<'reply,'turn,'source>(&mut self,_:&mut (),_:NativeAllocationEvent,reply:crate::NativeAllocationReply<'reply>)->Result<crate::NativeAllocationReplyComplete<'reply>,ValueError> where 'source:'turn{match self.saved.take(){Some(verdict)=>Ok(reply.complete(verdict)),None=>Ok(reply.pending())}}}
 let mut authority=NativeAllocationAuthority::new(Port{saved:None,calls:0});let mut transaction=None;authority.with_send_loan(&mut (),|loan|{let request=NativeAllocationRequest{bytes:8,owned_bytes:0,next_owned_bytes:8,maximum_bytes:8};loan.begin(request,true,&mut transaction).unwrap();assert_eq!(transaction.as_ref().unwrap().phase(),NativeAllocationTransactionPhase::QuoteStarted);assert!(transaction.as_mut().unwrap().take_verdict().is_none());assert!(loan.recover(transaction.as_mut().unwrap()).unwrap());assert!(transaction.as_mut().unwrap().take_verdict().unwrap().is_ok());loan.settle(transaction.as_mut().unwrap(),None).unwrap();assert!(transaction.as_mut().unwrap().take_verdict().unwrap().is_ok());loan.finish(&mut transaction).unwrap();}).unwrap();assert_eq!(authority.inspect_port(|port|port.calls),2);assert!(authority.into_port().is_ok());
}
